const patterns = [
  [/^(\d+) questions? available with these settings\.$/, (_, n) => `Доступно запитань із цими налаштуваннями: ${n}.`],
  [/^All (\d+) included$/, (_, n) => `Обрано всі: ${n}`],
  [/^(\d+) included$/, (_, n) => `Обрано: ${n}`],
  [/^Include categories \((\d+)\)$/, (_, n) => `Оберіть категорії (${n})`],
  [/^QUESTION (\d+) \/ (\d+)$/, (_, a, b) => `ЗАПИТАННЯ ${a} / ${b}`],
  [/^FOR (.+) POINTS$/, (_, n) => `ЗА ${n} БАЛІВ`],
  [/^(\d+) PLAYERS$/, (_, n) => `ГРАВЦІВ: ${n}`],
  [/^Secured: (.+) pts$/, (_, n) => `Гарантовано: ${n} балів`],
  [/^(.+) pts$/, (_, n) => `${n} балів`],
  [/^(.+), what’s your answer\?$/, (_, name) => `${name}, яка ваша відповідь?`],
  [
    /^(.+), your answer is locked\. Waiting for the other players…$/,
    (_, name) => `${name}, відповідь прийнято. Чекаємо на інших гравців…`,
  ],
  [/^Correct answer: (.+)$/, (_, answer) => `Правильна відповідь: ${answer}`],
  [
    /^The climb ends here\. You keep (.+) points\.$/,
    (_, n) => `Сходження завершено. Ви зберігаєте ${n} балів.`,
  ],
  [
    /^(\d+) of (\d+) answers locked\. (.+)$/,
    (_, a, b, tail) =>
      `Відповідей прийнято: ${a} із ${b}. ${tail === "Reveals automatically after your pick." ? "Правильна відповідь відкриється автоматично після вашого вибору." : "Відповіді відкриються, коли всі зроблять вибір або спливе хвилина."}`,
  ],
  [/^(\d+) questions$/, (_, n) => `Запитань: ${n}`],
  [/^(.+) · random$/, (_, name) => `${name} · випадково`],
  [/^(\d+) of (\d+) translated$/, (_, a, b) => `Перекладено ${a} із ${b}`],
];
export function translate(text, language) {
  if (language !== "uk" || !text.trim()) return text;
  const s = text.trim();
  let result = ukrainian[s] ?? categoryLabels[s];
  if (result === undefined && s.includes(" · ") && !s.startsWith("Secured:")) {
    const pieces = s.split(" · ").map((p) => translate(p, language));
    if (pieces.join(" · ") !== s) result = pieces.join(" · ");
  }
  if (result === undefined) {
    for (const [pattern, replacement] of patterns)
      if (pattern.test(s)) {
        result = s.replace(pattern, replacement);
        break;
      }
  }
  return result === undefined ? text : text.replace(s, result);
}
export function localize(root, language) {
  if (language !== "uk") return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  let node;
  while ((node = walker.nextNode())) {
    if (!node.parentElement.closest("[data-no-translate],script,style"))
      node.nodeValue = translate(node.nodeValue, language);
  }
  for (const el of root.querySelectorAll("[placeholder],[aria-label]")) {
    if (el.closest("[data-no-translate]")) continue;
    for (const name of ["placeholder", "aria-label"])
      if (el.hasAttribute(name))
        el.setAttribute(name, translate(el.getAttribute(name), language));
  }
}
